package dailyassignments;

public class Program_MultipleOf5 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		 int num=1;
	        while(num<=5)
	        {
	        	int mul=num*5;
	        	System.out.println(num+" multiplied by 5 is "+mul);
	        	num++;
	        }
	}

}
